insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'unf-disclosure-required'), 1, 'yes', 'UNF says its athletes must report all NIL activities to the Athletics Department through NILGo.com. UNF''s policy says athletes must report all NIL deals, paid, unpaid or in-kind, as the NCAA or the College Sports Commission directs. The handbook says to disclose as the Compliance Office instructs.', 'What the school adds: UNF says ALL activities, with no dollar minimum stated on the guide. What the school adds: UNF counts unpaid and in-kind deals and makes the athlete responsible for timely reporting. No deadline is given in UNF''s own words.', 'UNF NIL Reference Guide (2025-26), Additional UNF NIL Policies; UNF Policy 5.0110P and 2026-27 Student-Athlete Handbook', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Report every NIL activity through NIL Go.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'unf-disclosure-required' and v.is_current), (select id from sources where slug = 'unf-s2'), 'Additional UNF NIL Policies', 'SAs are obligated to report ALL NIL activities to the Athletics Department through NILGo.com.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
