insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-school-payments'), 1, 'yes_with_conditions', 'Stetson''s policy says the university, or an entity it owns, controls, funds or operates, may enter a written license or endorsement agreement for an athlete''s NIL. Stetson also announced it will opt in to the House settlement starting in 2026-27. Stetson''s policy says the university, or an entity it owns, controls, funds or operates, may sign a written license or endorsement agreement for an athlete''s NIL. It excludes agreements that pay for broadcast rights to games.', 'The policy limits the agreement to a period not to exceed the athlete''s period of eligibility.', 'Stetson University Name, Image, and Likeness Policy v.5, page 3; news release December 18, 2025; Stetson Name, Image, and Likeness Policy v.5, Policy (page 3)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'DEPENDS', 'Stetson may sign NIL agreements with athletes and opts in to House from 2026-27.');
