insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-school-staff-involvement'), 1, 'yes_with_conditions', 'Stetson''s policy says the university may act as a marketing agent for an athlete on noninstitutional NIL contracts. It says a parent, guardian, lawyer or other representative may assist the athlete unless the athlete waives that help in writing.', NULL, 'Stetson University Name, Image, and Likeness Policy v.5, page 3, item b', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'Stetson may act as a marketing agent for outside deals.');
