insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-pay-for-play'), 1, 'no', 'Stetson''s policy says an athlete may use their NIL to promote business activities as long as the athlete gets no pay in exchange for athletics participation or achievements.', 'The policy was last revised September 16, 2025. Stetson later announced it opts in to the House settlement from 2026-27. The policy text was not changed to mention direct school payments.', 'Stetson Name, Image, and Likeness Policy v.5, Policy', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'NO', 'No pay for playing or for results.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-pay-for-play' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Policy, paragraph 1 (page 2)', 'so long as the student-athlete does not receive any compensation in exchange for their athletics participation or achievements', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
