insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-deal-terms'), 1, 'yes_with_conditions', 'Stetson''s policy says NIL pay must be for a valid business purpose. It says rates and terms must match what similar people with similar NIL value are paid. Stetson''s policy warns that Pell Grant or need based aid could be affected by NIL pay and sends questions to the Office of Student Financial Planning. It says earned income must be reported on the athlete''s tax return.', NULL, 'Stetson Name, Image, and Likeness Policy v.5, Policy; Stetson Name, Image, and Likeness Policy v.5, Procedures (page 5)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'DEPENDS', 'Pay must match a real business purpose and market rates.');
