insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-deal-terms' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Procedures (page 5)', 'Pell Grant or need based financial aid could be impacted based on compensation from Name, Image and Likeness.', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-deal-terms' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Procedures (page 5)', 'Earned income will need to be reported on the student-athlete’s annual tax return.', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
