insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-school-name-reference'), 1, 'yes_with_conditions', 'Stetson''s policy says an athlete''s business promotion may mention their role in college sports and may mention Stetson University. If they do, they must add a disclaimer that the views or services are theirs alone.', NULL, 'Stetson Name, Image, and Likeness Policy v.5, Policy', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'DEPENDS', 'Yes, with an ''opinions are my own'' style disclaimer.');
