insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('stetson-school-logos-marks', (select id from rule_topics where slug = 'school-logos-marks'), 'institution', (select id from institutions where slug = 'stetson-university'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-school-logos-marks'), 1, 'yes_with_conditions', 'Stetson''s policy says any use of Stetson''s name, marks or symbols must follow Stetson Athletics'' Branding and Style Guides. The 2023 athletics brand guide says use of the logos without consent is prohibited.', 'The policy does not name who gives consent to an athlete. The 2023 guide names Learfield Licensing for vendor requests. Stetson announced Affinity Licensing as its licensing agency from July 1, 2026, so the guide is outdated on that point. The policy does not mention uniforms.', 'Stetson Name, Image, and Likeness Policy v.5, Policy; Stetson Hatters Brand Identity Guide v2.0', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'CHECK_FIRST', 'Follow the Branding and Style Guides. Get consent first.');
