insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-prohibited-categories'), 1, 'no', 'Stetson''s policy says athletes cannot sign a deal that ties the university name or marks to products or services that compete with Stetson Athletics'' exclusive sponsors. It also says athletes should not sign deals that break NCAA rules, Stetson policies or the law, or that reflect badly on Stetson.', 'The policy does not list product categories such as gambling, alcohol or tobacco.', 'Stetson Name, Image, and Likeness Policy v.5, Policy', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'NO', 'No deals that pair Stetson''s name or marks with a rival of an exclusive sponsor.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-prohibited-categories' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Policy, paragraph 5 (page 2)', 'Student-athletes cannot enter into a contract or transaction that associates the university name and/or marks with products or services that are competitive to Stetson’s Athletics exclusive sponsors in conflict with a university contract (e.g. Coca-Cola, Nike).', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-prohibited-categories' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Policy, paragraph 5 (page 2)', 'student-athletes should not enter into contract or transactions that violate NCAA legislation, Stetson University policies, Federal or State Laws; or reflect negatively on Stetson University and/or the Stetson University Athletics program.', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
