insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-disclosure-required'), 1, 'yes', 'Stetson''s policy says an athlete must disclose NIL contracts or transactions to NIL GO. Deals from non-school payors worth $600 or more in total must be reported, with written documentation, within five business days of signing.', 'The $600 total counts multiple deals or payments from the same or substantially the same third party, including affiliates. Athletes also attest on NIL GO registration that all such deals will be reported.', 'Stetson Name, Image, and Likeness Policy v.5, Policy (page 3) and Procedures (page 5)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'YES', 'Report to NIL GO within five business days. $600 total is the threshold.');
