insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-agents'), 1, 'yes', 'Stetson''s policy says all Stetson athletes are entitled, and advised, to get professional representation by an athlete agent or attorney to secure pay for the use of their NIL.', 'The policy does not state agent registration or licensing requirements. It says a service provider may help move payments only if the business using the NIL is the source of the money.', 'Stetson Name, Image, and Likeness Policy v.5, Policy (page 4)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'YES', 'Yes. Stetson advises getting an agent or attorney for NIL.');
