insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('stetson-international-athletes', (select id from rule_topics where slug = 'international-athletes'), 'institution', (select id from institutions where slug = 'stetson-university'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-international-athletes'), 1, 'only_with_approval', 'Stetson''s policy says international athletes usually cannot do paid NIL work while in the United States. It says they must consult the Stetson WORLD office before any paid NIL activity. It says they may do NIL work from their home country during vacation periods, with pay going to a home country bank account, and should submit it to NIL GO.', 'The policy asks athletes to document that they are abroad with an I-94 travel history, flight itinerary and port of entry stamp.', 'Stetson Name, Image, and Likeness Policy v.5, International Students (pages 4 to 5)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'CHECK_FIRST', 'Talk to the WORLD office first. Paid NIL in the US on a student visa is not allowed.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-international-athletes' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'International Students (page 4)', 'International student-athletes must consult with the WORLD office prior to engaging in any paid NIL activities', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-international-athletes' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'International Students (page 5)', 'it remains impermissible to engage in NIL activities while in the US on a student visa.', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-international-athletes' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'International Students (page 5)', 'During vacation periods, international student-athletes may engage in NIL activities from their home country', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
