insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'ocps-nil-allowed'), 1, 'not_addressed', 'OCPS board policy says all district high schools are FHSAA members and follow FHSAA rules. The policy does not mention NIL.', 'Policy JJI was adopted in 2008, before FHSAA allowed NIL. It adds no district NIL rule.', 'OCPS School Board Policy JJI, section (1)', 'researched', 'PUBLIC_POLICY_NOT_LOCATED', 'raw_source_text', 'Not located in the public sources reviewed as of October 3, 2026.', 'NOT_PUBLICLY_SPECIFIED', 'The district policy points to FHSAA rules and says nothing on NIL.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ocps-nil-allowed' and v.is_current), (select id from sources where slug = 'ocps-d2'), 'Policy JJI (1)', 'All district high schools shall be members of the Florida High School --- Athletics Association, Inc. (FHSAA) and shall be governed by the rules and regulations adopted by FHSAA.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
