insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer, nil_specific) values ((select id from rules where slug = 'ocps-penalties'), 1, 'yes_with_conditions', 'OCPS says athletes are under all school board rules and the Code of Student Conduct at athletic events and practices. OCPS also says the Board can withhold the privilege of taking part in extracurricular activities.', 'These are general conduct rules. They are not written about NIL.', 'OCPS School Board Policy JJI (8) and Policy JJ', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'District conduct rules apply to athletes and can cost you the right to play.', FALSE);
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ocps-penalties' and v.is_current), (select id from sources where slug = 'ocps-d2'), 'Policy JJI (8)', 'All students shall be subject to all school board rules and to the Code of Student Conduct while attending athletic events and practices.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
