insert into rules (slug, rule_topic_id, scope_type, district_id, applies_to) values ('ocps-school-facilities', (select id from rule_topics where slug = 'school-facilities'), 'district', (select id from school_districts where slug = 'orange-county-public-schools'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer, nil_specific) values ((select id from rules where slug = 'ocps-school-facilities'), 1, 'only_with_approval', 'OCPS says school board property cannot be used to advertise or promote a business unless there is a contract for advertising under Policy KHB. OCPS says the principal or the Chief Facilities Officer may approve outside use of buildings, grounds or equipment through a facility use agreement. Business groups may be charged rent and must show insurance.', 'The policy is about advertising on district property in general. It does not mention student NIL deals. Display ads need a written Display Advertising Agreement arranged through the OCPS Marketing and Events Department. Ads on district property also cannot promote alcohol, tobacco, drugs, weapons or gambling. The policy does not mention filming, photo shoots or NIL. The district Facilities page links facility rental to Facilitron.', 'OCPS School Board Policy KHB, sections (1) and (2)(c); OCPS School Board Policy KF', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'No business promotion on OCPS property without a district advertising contract.', FALSE);
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ocps-school-facilities' and v.is_current), (select id from sources where slug = 'ocps-d4'), 'Policy KHB (1)', 'shall not be used for advertising or otherwise promoting the interests of any commercial, religious, political, or other non-district agency or organization except by contractual agreement for “Advertising” as defined in this policy.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ocps-school-facilities' and v.is_current), (select id from sources where slug = 'ocps-d4'), 'Policy KHB (2)(c)(i)', 'Such Display Advertising Agreement shall be provided through and assisted by the Marketing and Events Department.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ocps-school-facilities' and v.is_current), (select id from sources where slug = 'ocps-d4'), 'Policy KHB (6)(b)', 'No advertisement shall promote or contain references to alcohol, tobacco, drugs, drug paraphernalia, weapons, or lewd, vulgar, obscene, pornographic or illegal materials or activities, gambling, violence, hatred, sexual conduct or sexually explicit material', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ocps-school-facilities' and v.is_current), (select id from sources where slug = 'ocps-d5'), 'Policy KF, opening paragraph (spacing normalized)', 'The use of Board Property shall not interfere with the educational program of the district or school.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
