insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'ocps-school-logos-marks'), 1, 'not_addressed', 'The OCPS Style Guide page sets rules for the district logo in district communications. It does not state a rule for students or outside businesses using district or school logos.', 'No School Board policy on school names, logos or trademarks was found in the policy index. Policy KHB only speaks about product brand names and logos.', 'OCPS Style Guide Home, Logos section', 'researched', 'PUBLIC_POLICY_NOT_LOCATED', 'raw_source_text', 'Not located in the public sources reviewed as of October 3, 2026.', 'NOT_PUBLICLY_SPECIFIED', 'No public district rule on using school logos in NIL content was found.');
