insert into rules (slug, rule_topic_id, scope_type, district_id, applies_to) values ('scps-nil-allowed', (select id from rule_topics where slug = 'nil-allowed'), 'district', (select id from school_districts where slug = 'seminole-county-public-schools'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'scps-nil-allowed'), 1, 'yes_with_conditions', 'The Seminole County School Board says it recognizes the right of high school athletes to use and benefit from their name, image and likeness. It says athletes must still follow Florida law, State Board of Education rules, Board policies and FHSAA bylaws. The Board adds that failing to follow these rules may affect an athlete''s amateur status.', 'The policy is one paragraph. It sets no district process, form, contact or approval step. The detail comes from FHSAA rules.', 'SCPS Board Policy 2431.06', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Yes. The district recognizes NIL, within FHSAA and Board rules.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'scps-nil-allowed' and v.is_current), (select id from sources where slug = 'scps-t1'), 'Policy 2431.06, first sentence', 'The School Board recognizes the rights of high school student-athletes to use and benefit from their name, image, and likeness (NIL) in various activities.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'scps-nil-allowed' and v.is_current), (select id from sources where slug = 'scps-t1'), 'Policy 2431.06', 'Likewise, student athletes must comply with all applicable bylaws of the Florida High School Athletics Association (FHSAA).', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'scps-nil-allowed' and v.is_current), (select id from sources where slug = 'scps-t1'), 'Policy 2431.06, last sentence', 'Failure to adhere to any of these laws, rules, and/or regulations may, among other things, impact the amateur status of a student athlete.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
