insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer, nil_specific) values ((select id from rules where slug = 'scps-school-name-reference'), 1, 'only_with_approval', 'The Seminole County School Board says its name, students, staff and District facilities shall not be used for commercial advertising or to promote an outside organization without approval of the Board or its designee.', 'This is a general advertising policy. It does not mention NIL or student-athletes by name. How it applies to an athlete''s own NIL deal is not stated.', 'SCPS Board Policy 9700.01', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Using the district name, students or facilities in an ad needs Board approval.', FALSE);
