insert into policy_searches (institution_id, public_policy_found, search_date, locations_checked, locations_unreachable, searched_by, notes) values ((select id from institutions where slug = 'hagerty-high-school-oviedo'), FALSE, '2026-10-04', ARRAY['hagertyhigh.scps.k12.fl.us (home page and navigation)','hagertyhigh.scps.k12.fl.us/athletics-home (Athletics Home link list)','hagertyhigh.scps.k12.fl.us/athletics-staff (Athletics Staff)','hagertyhigh.scps.k12.fl.us/sports-offerings (document viewer did not load)','Web search for Seminole County Public Schools NIL policy (no official SCPS result returned)','FHSAA Membership List 2026-27, dated August 28, 2026 (school found on the list)','Hagerty Athletic Program Offerings 2026-2027 (PDF, read in full)','Hagerty Online Sports Physical Submission directions 2026-2027 (PDF, read in full; names athleticclearance.com; no mention of Form GA1 or NIL)']::text[], ARRAY['Hagerty Athletic Boosters site (https://www.hagertyathleticboosters.org/): not opened.']::text[], 'Claude (automated source research)', 'School-specific NIL policy: Not located in the public sources reviewed as of October 4, 2026. The 2026-27 clearance directions name athleticclearance.com and do not mention Form GA1 or NIL.');
insert into policy_searches (institution_id, public_policy_found, search_date, locations_checked, locations_unreachable, searched_by, notes) values ((select id from institutions where slug = 'winter-springs-high-school-winter-springs'), FALSE, '2026-10-04', ARRAY['winterspringshs.scps.k12.fl.us/athletics-home (Athletics Home and athletics menu)','winterspringshs.scps.k12.fl.us/athletics-directors-message (Director''s Message)','winterspringshs.scps.k12.fl.us/coaches (Coaches)','winterspringshs.scps.k12.fl.us/athletics-sponsors (Sponsors)','winterspringshs.scps.k12.fl.us/athletics-facilities (Facilities)','winterspringshs.scps.k12.fl.us/winter-sports (team menu)','Web search for Seminole County Public Schools NIL policy (no official SCPS result returned)','FHSAA Membership List 2026-27, dated August 28, 2026 (school found on the list)']::text[], ARRAY['''WSHS Athletic Clearance Directions'' PDF linked from Athletics Home: not opened (link URL not captured).','2024-25 WSHS Sponsorship Program PDF (https://files.smartsites.parentsquare.com/6721/2024-25_wshs_sponsorship_program_campaign_for_our_kids_.pdf): not opened.']::text[], 'Claude (automated source research)', 'School-specific NIL policy: Not located in the public sources reviewed as of October 4, 2026. The athletics home page describes clearance through the Athletic Clearance website. It does not mention NIL or Form GA1 in the text read.');
insert into policy_searches (institution_id, public_policy_found, search_date, locations_checked, locations_unreachable, searched_by, notes) values ((select id from institutions where slug = 'crooms-academy-of-information-technology-sanford'), FALSE, '2026-10-04', ARRAY['cait.scps.k12.fl.us/about-us (About Us)','cait.scps.k12.fl.us/athletics-home (Athletics Home and athletics menu)','cait.scps.k12.fl.us/forms-clearance (Forms & Clearance)','cait.scps.k12.fl.us/eligibility (Eligibility)','cait.scps.k12.fl.us/banner-sports-programs (Banner Sports Programs)','Web search for Seminole County Public Schools NIL policy (no official SCPS result returned)','FHSAA Membership List 2026-27, dated August 28, 2026 (school found on the list)']::text[], ARRAY['''Sponsor Packet'' document linked from Banner Sports Programs: not opened (link URL not captured).','Athletics handbook link reported on Athletics Home: not opened (link URL not captured).']::text[], 'Claude (automated source research)', 'School-specific NIL policy: Not located in the public sources reviewed as of October 4, 2026. Crooms does field interscholastic teams, per its own athletics pages. The Forms & Clearance page names Athletic Clearance, the EL2 form and an ECG form. It does not mention NIL or Form GA1 in the text read.');
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'university-of-florida'), 'Overview of Gators NIL', 'UF publishes an athlete-facing NIL overview (dated August 6, 2025 in its URL) rather than a formal policy document. It covers what athletes can do, the NIL Go reporting rule, use of Gators marks and gear, prohibited vendors, international athletes and the support UF offers. UF''s older "Guidelines for Name, Image, and Likeness" page now reads "Updated information coming soon."', 'published', (select id from sources where slug = 'uf-nil-overview'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'florida-state-university'), 'Florida State Compliance: Agents & Advisors and NCAA Guidelines on NIL', 'This is the FSU Athletics compliance page. It covers booster rules, agent registration with FSU, and how athletes disclose third-party NIL deals in NIL Go. It is a web page, not a signed policy document.', 'published', (select id from sources where slug = 'fsu-s1'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'university-of-miami'), 'Miami NIL Policy (Miami NIL Program / Guidelines)', 'This is the athletics department NIL policy page. It covers disclosure, who may pay athletes, agents, international athletes and use of university marks. It was written under the NCAA interim policy and has not been updated for the House settlement.', 'outdated', (select id from sources where slug = 'miami-s2'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'university-of-south-florida'), 'USF Name, Images, Likeness Guidelines (and linked USF NIL Policy, updated 7.13.2021)', 'This is the USF Athletics NIL guidelines page with an FAQ. It covers who may pay athletes, use of USF marks and uniforms, banned vendor types, disclosure and agents. It was written before the House settlement and is not treated as current.', 'outdated', (select id from sources where slug = 'usf-s2'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'florida-atlantic-university'), 'FAU Student-Athlete Handbook 2026-27, Name, Image, Likeness (NIL) section', 'This is the athletics department handbook for FAU athletes. Its NIL section lists the conditions for NIL, what athletes may not do, what staff may do, and a note for international students. It is short and does not name the disclosure platform or a deadline.', 'published', (select id from sources where slug = 'fau-s2'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'florida-international-university'), 'FIU Policy 910.001, Student-Athlete Name, Image, and Likeness', 'This is FIU''s university policy on athlete NIL. It covers what NIL pay is allowed, use of FIU logos, uniforms and facilities, disclosure, and who reviews deals. The 2026-2027 Student-Athlete Handbook repeats it and adds the INFLCR app, banned categories and NIL Go steps.', 'published', (select id from sources where slug = 'fiu-s3'), '2021-07-01', 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'florida-am-university'), 'Athletics Compliance: Name, Image, Likeness (NIL) guidance for students', 'This is a section of the FAMU Office of Compliance and Ethics web page. It explains NIL in plain terms and gives a short compliance checklist, tips on deals, brand and time management, and a link to a question checklist. It is undated and does not mention the House settlement or NIL Go.', 'unconfirmed', (select id from sources where slug = 'famu-s1'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'jacksonville-university'), 'Name, Image and Likeness (JU Athletics)', 'This is the NIL page on the JU athletics site. It covers disclosure through INFLCR, logo and facility approval, agents, banned deal categories, boosters and collectives, and international athletes. It dates from 2022 and cites Florida law and NCAA guidance from before the House settlement.', 'outdated', (select id from sources where slug = 'ju-s1'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'university-of-north-florida'), 'UNF Policy 5.0110P, Intercollegiate Athletes: Name, Image and Likeness', 'UNF''s formal university policy on athlete NIL, effective October 25, 2021 and revised January 20, 2026. It covers reporting, logos and uniforms, facilities, agents, prohibited deals, workshops and how violations are handled. The 2026-27 Student-Athlete Handbook and a one-page NIL Reference Guide summarise it.', 'published', (select id from sources where slug = 'unf-t1'), '2021-10-25', 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'florida-gulf-coast-university'), 'FGCU Name, Image, Likeness', 'A web page of NIL guidance for FGCU athletes. It covers logos and uniforms, facilities, disclosure, agents and attorneys, minors, and international athletes. Parts of it appear to predate the House settlement.', 'outdated', (select id from sources where slug = 'fgcu-s1'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'stetson-university'), 'Stetson University Name, Image, and Likeness Policy', 'A six page Stetson University policy, last revised September 16, 2025. It covers what NIL activity is allowed, reporting to NIL Go, agents, use of Stetson''s name and marks, sponsor conflicts, facilities, workshops, international athletes and late disclosure. All six pages were read on screen on October 4, 2026.', 'published', (select id from sources where slug = 'stetson-s1'), '2025-09-16', 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'boone-high-school-orlando'), 'William R. Boone High School Department of Athletics Social Media Policy 2025-2026', 'A one-page policy from the Boone athletic department. It says athletes may use social media, lists banned kinds of posts and lists penalties. It does not mention NIL, sponsors or paid posts.', 'published', (select id from sources where slug = 'boone-hs-s4'), NULL, 'needs_verification', FALSE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'winter-park-high-school-winter-park'), '''NIL'' menu item on winterparkathletics.org (links to FHSAA Form GA1)', 'The Winter Park athletics site has a menu item named NIL under ''More''. It opens a hosted copy of the FHSAA GA1 Affidavit of Amateurism dated August 2024. The site gives no school-written NIL guidance beside it.', 'unconfirmed', (select id from sources where slug = 'winter-park-hs-s1'), NULL, 'needs_verification', TRUE);
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status, covers_nil) values ((select id from institutions where slug = 'windermere-high-school-windermere'), 'Windermere High School Department of Athletics Code of Conduct 2021-22', 'Windermere''s athletics site links this as the Student-Athlete Handbook. It covers attendance, conduct, social media behavior, uniforms and equipment, travel and injuries. It is dated 2021-22 and does not mention NIL, sponsorships or use of the school logo.', 'outdated', (select id from sources where slug = 'windermere-hs-s6'), NULL, 'needs_verification', FALSE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-florida'), 'Gators NIL Exchange', 'marketplace', 'UF says the exchange "allows fans, alumni, and local businesses to directly connect with Gator athletes to offer them opportunities."', 'https://floridagators.com/sports/2021/12/16/gators-made-name-image-likeness.aspx', (select id from sources where slug = 'uf-gators-made'), 'researched', 10, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-florida'), 'Florida Victorious', 'nil_entity', 'UF''s NIL page describes Florida Victorious as "an exclusive community for Gator Nation" that "strives to be the model NIL entity in collegiate athletics." Whether a payor counts as "associated" with a school is decided in NIL Go review.', 'https://floridavictorious.com/', (select id from sources where slug = 'uf-gators-made'), 'researched', 20, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-florida'), 'Gators Sports Properties', 'sponsorship_sales', 'The route for companies that want to sponsor or partner with the Florida Gators and their athletes.', 'https://floridagators.com/sports/2015/12/10/_sponsors_', (select id from sources where slug = 'uf-gators-made'), 'researched', 30, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-florida'), 'NIL Suite, Hawkins Center, Gators Experience and GatorMade', 'education', 'UF''s in-house support: one-on-one NIL advising, content help, and financial literacy, brand building and education workshops.', 'https://floridagators.com/sports/2025/8/6/overview-name-image-likeness', (select id from sources where slug = 'uf-gators-made'), 'researched', 40, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'florida-state-university'), 'The Battle''s End', 'collective', 'FSU Athletics announced it as "the official NIL collective of Florida State Athletics" on August 27, 2025.', 'https://thebattlesend.com/pages/join-the-battles-end-fsu-nil', (select id from sources where slug = 'fsu-s5'), 'researched', 10, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'florida-state-university'), 'Rising Spear', 'collective', 'FSU''s August 27, 2025 release said this collective would be dissolved and its work moved into The Battle''s End. The school says this is no longer active.', 'https://seminoles.com/news/2025/8/27/florida-state-athletics-announces-strategic-nil-partnership-with-the-battles-end-collective', (select id from sources where slug = 'fsu-s5'), 'researched', 20, FALSE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'florida-state-university'), 'Florida State Global Partnerships (Legends)', 'sponsorship_sales', 'FSU says "Florida State Global Partnerships is the official multimedia rights holder for Florida State Athletics" and that NIL campaigns using FSU Athletic marks must be coordinated through it.', 'https://seminoles.com/feature/the-brand/', (select id from sources where slug = 'fsu-s4'), 'researched', 30, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'florida-state-university'), 'FSU Office of Trademark Licensing', 'licensing', 'FSU says NIL items with FSU logos or marks "must go through the Office of Trademark Licensing".', 'https://seminoles.com/feature/the-brand/', (select id from sources where slug = 'fsu-s4'), 'researched', 40, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'florida-state-university'), 'INFLCR Exchange (Florida State)', 'marketplace', 'FSU''s NIL page links "Connect with student-athletes" to an INFLCR exchange for Florida State. Current status not confirmed.', 'https://dash.inflcr.com/exchange/florida-state-university', (select id from sources where slug = 'fsu-s2'), 'researched', 50, NULL);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'florida-state-university'), 'The Player Shop', 'licensing', 'FSU''s NIL page links to a store for student-athlete merchandise sold under group licensing. Current status not confirmed.', 'https://shop.seminoles.com/the-player-shop/x-49461892+z-895950-4065891985', (select id from sources where slug = 'fsu-s2'), 'researched', 60, NULL);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'florida-state-university'), 'FSU group licensing programs (OneTeam, The Brandr Group, The NIL Store)', 'licensing', 'FSU''s 2024 marks document says group licensing lets athletes opt in to co-branded merchandise, and names OneTeam, The Brandr Group and The NIL Store. "Group licensing is passive income". Current status not confirmed.', 'https://seminoles.com/documents/2024/12/12/NIL_-_Use_of_Marks_and_Group_Licensing.pdf', (select id from sources where slug = 'fsu-t1'), 'researched', 70, NULL);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-miami'), 'Canes Connection', 'collective', 'Miami Athletics announced that "Canes Connection is now its Official Name, Image & Likeness (NIL) Collective."', 'https://canesconnection.com/', (select id from sources where slug = 'miami-s7'), 'researched', 10, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-miami'), 'Miami Exchange (INFLCR)', 'marketplace', 'Miami says athletes "are able to maximize NIL opportunities through the Miami Exchange." Current status not confirmed.', 'https://app.inflcr.com/exchange/university-of-miami', (select id from sources where slug = 'miami-s1'), 'researched', 20, NULL);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-miami'), 'Altius Sports Partners', 'education', 'Miami says Altius "provides ongoing strategic guidance on NIL for Miami Athletics". Current status not confirmed.', 'https://miamihurricanes.com/nil/', (select id from sources where slug = 'miami-s1'), 'researched', 30, NULL);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-miami'), 'Legends Global (sponsorship rights)', 'sponsorship_sales', 'Miami says "Sponsorship rights are managed by Legends Global".', 'https://miamihurricanes.com/nil/', (select id from sources where slug = 'miami-s1'), 'researched', 40, TRUE);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order, is_current) values ((select id from institutions where slug = 'university-of-miami'), 'Fanatics Licensing Management', 'licensing', 'Miami says "licensing/retail rights are managed by Fanatics Licensing Management."', 'https://miamihurricanes.com/nil/', (select id from sources where slug = 'miami-s1'), 'researched', 50, TRUE);
